mapper.select:
SELECT * FROM ( SELECT a.*, ROWNUM as rn FROM ( SELECT cc.CENTER_ID, cc.CENTER_CODE, cc.CENTER_NAME, cc.CENTER_TYPE, CASE cc.CENTER_TYPE WHEN 1 THEN '成本中心' WHEN 2 THEN '利润中心' WHEN 3 THEN '投资中心' ELSE '未知' END as CENTER_TYPE_NAME, cc.PARENT_CENTER_ID, cc.PARENT_CENTER_NAME, cc.CENTER_LEVEL, cc.IS_LEAF, cc.MANAGER_ID, cc.MANAGER_NAME, cc.COST_ALLOCATION_METHOD, CASE cc.COST_ALLOCATION_METHOD WHEN 1 THEN '直接分摊' WHEN 2 THEN '阶梯分摊' WHEN 3 THEN '比例分摊' ELSE '未知' END as ALLOCATION_METHOD_NAME, cc.IS_ENABLED, cc.BOOK_ID, cc.TENANT_ID, cc.CREATE_TIME, cc.UPDATE_TIME, cc.CREATOR, cc.UPDATER, cc.VERSION FROM T_COST_CENTER cc WHERE cc.IS_DELETED = 0
AND cc.BOOK_ID = #{param.bookId}
AND cc.TENANT_ID = #{param.tenantId}
AND cc.CENTER_CODE LIKE '%' || #{param.centerCode} || '%'
AND cc.CENTER_NAME LIKE '%' || #{param.centerName} || '%'
AND cc.CENTER_TYPE = #{param.centerType}
AND cc.IS_ENABLED = #{param.isEnabled}
ORDER BY cc.CENTER_CODE ASC ) a WHERE ROWNUM <= (#{offset} + #{limit}) ) WHERE rn > #{offset}

SELECT COUNT(1)
FROM T_COST_CENTER cc
LEFT JOIN T_COST_CENTER pcc ON cc.PARENT_CENTER_ID = pcc.CENTER_ID AND pcc.IS_DELETED = 0
LEFT JOIN TBL_STAFF s ON cc.MANAGER_ID = s.STAFFID
WHERE cc.IS_DELETED = 0

    AND cc.BOOK_ID = #{param.bookId}


    AND cc.TENANT_ID = #{param.tenantId}


    AND cc.CENTER_CODE LIKE '%' || #{param.centerCode} || '%'


    AND cc.CENTER_NAME LIKE '%' || #{param.centerName} || '%'


    AND cc.CENTER_TYPE = #{param.centerType}


    AND cc.IS_ENABLED = #{param.isEnabled}

SELECT cc.CENTER_ID as centerId, cc.CENTER_CODE as centerCode, cc.CENTER_NAME as centerName, cc.CENTER_TYPE as centerType, CASE cc.CENTER_TYPE WHEN 1 THEN '成本中心' WHEN 2 THEN '利润中心' WHEN 3 THEN '投资中心' ELSE '未知' END as centerTypeName, cc.PARENT_CENTER_ID as parentCenterId, cc.PARENT_CENTER_NAME as parentCenterName, cc.CENTER_LEVEL as centerLevel, cc.IS_LEAF as isLeaf, cc.MANAGER_ID as managerId, cc.MANAGER_NAME as managerName, cc.COST_ALLOCATION_METHOD as costAllocationMethod, CASE cc.COST_ALLOCATION_METHOD WHEN 1 THEN '直接分摊' WHEN 2 THEN '阶梯分摊' WHEN 3 THEN '比例分摊' ELSE '未知' END as allocationMethodName, cc.IS_ENABLED as isEnabled, cc.BOOK_ID as bookId, cc.CREATE_TIME as createTime, cc.UPDATE_TIME as updateTime, cc.VERSION as version FROM T_COST_CENTER cc WHERE cc.IS_DELETED = 0
AND cc.BOOK_ID = #{param.bookId}
AND cc.TENANT_ID = #{param.tenantId}
AND cc.CENTER_CODE LIKE '%' || #{param.centerCode} || '%'
AND cc.CENTER_NAME LIKE '%' || #{param.centerName} || '%'
AND cc.CENTER_TYPE = #{param.centerType}
AND cc.IS_ENABLED = #{param.isEnabled}
ORDER BY cc.CENTER_CODE ASC

SELECT CENTER_ID as value, CENTER_CODE as code, CENTER_NAME as label, CENTER_TYPE as centerType, PARENT_CENTER_ID as parentId, CENTER_LEVEL as level, IS_LEAF as isLeaf FROM T_COST_CENTER WHERE IS_DELETED = 0 AND IS_ENABLED = 1
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
ORDER BY CENTER_CODE ASC

SELECT COUNT(1)
FROM T_COST_CENTER
WHERE CENTER_CODE = #{centerCode}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}
  AND IS_DELETED = 0

    AND CENTER_ID != #{centerId}

SELECT TO_CHAR(cb.BUDGET_ID) budgetId, -- 使用TO_CHAR确保ID以字符串形式返回，避免JavaScript大整数精度丢失 TO_CHAR(cb.CENTER_ID) centerId, -- 使用TO_CHAR确保ID以字符串形式返回，避免JavaScript大整数精度丢失 cc.CENTER_CODE centerCode, cc.CENTER_NAME centerName, cb.BUDGET_YEAR budgetYear, cb.BUDGET_QUARTER budgetQuarter, cb.TOTAL_BUDGET totalBudget, cb.ACTUAL_COST actualCost, cb.REMAINING_BUDGET remainingBudget, cb.COST_CATEGORY costCategory, cb.STATUS status, cb.REMARK remark, cb.BUDGET_MANAGER budgetManager, cb.CONTROL_STRATEGY controlStrategy, cb.CREATE_TIME createTime, cb.UPDATE_TIME updateTime FROM T_COST_BUDGET cb LEFT JOIN T_COST_CENTER cc ON cb.CENTER_ID = cc.CENTER_ID AND cc.IS_DELETED = 0 WHERE cb.IS_DELETED = 0
AND cb.CENTER_ID = #{param.centerId}
AND cb.BUDGET_YEAR = #{param.budgetYear}
AND cb.BUDGET_QUARTER = #{param.budgetQuarter}
AND cb.COST_CATEGORY = #{param.costCategory}
AND cb.STATUS = #{param.status}
AND cc.BOOK_ID = #{param.bookId}
AND cc.TENANT_ID = #{param.tenantId}
ORDER BY cb.CREATE_TIME DESC

SELECT COALESCE(SUM(cb.TOTAL_BUDGET), 0) AS "totalBudget", COALESCE(SUM(cb.ACTUAL_COST), 0) AS "actualCost", COALESCE(SUM(cb.REMAINING_BUDGET), 0) AS "remainingBudget", COALESCE(COUNT(cb.BUDGET_ID), 0) AS "budgetCount", COALESCE(COUNT(CASE WHEN cb.STATUS = 1 THEN 1 END), 0) AS "activeCount", COALESCE(COUNT(CASE WHEN cb.STATUS = 0 THEN 1 END), 0) AS "inactiveCount", -- 预警中心：执行率 80%~100% COALESCE(COUNT(CASE WHEN cb.TOTAL_BUDGET > 0 AND cb.ACTUAL_COST / cb.TOTAL_BUDGET >= 0.8 AND cb.ACTUAL_COST / cb.TOTAL_BUDGET < 1.0 THEN 1 END), 0) AS "warningCount", -- 超支中心：执行率 ≥ 100% COALESCE(COUNT(CASE WHEN cb.TOTAL_BUDGET > 0 AND cb.ACTUAL_COST / cb.TOTAL_BUDGET >= 1.0 THEN 1 END), 0) AS "overBudgetCount", -- 平均执行率 CASE WHEN COALESCE(SUM(cb.TOTAL_BUDGET), 0) > 0 THEN ROUND(SUM(cb.ACTUAL_COST) * 100.0 / SUM(cb.TOTAL_BUDGET), 2) ELSE 0 END AS "avgExecutionRate" FROM T_COST_BUDGET cb LEFT JOIN T_COST_CENTER cc ON cb.CENTER_ID = cc.CENTER_ID AND cc.IS_DELETED = 0 WHERE cb.IS_DELETED = 0
AND cb.BUDGET_ID IN
#{id,jdbcType=VARCHAR}
AND cb.BUDGET_YEAR = #{param.period}
AND cb.CENTER_ID = #{param.centerId,jdbcType=VARCHAR}
AND cb.COST_CATEGORY = #{param.costCategory}
AND cb.STATUS = #{param.status}
AND cc.BOOK_ID = #{param.bookId}
AND cc.TENANT_ID = #{param.tenantId}
AND cb.BUDGET_ID IN
#{bid}

SELECT TO_CHAR(cb.BUDGET_ID) AS BUDGET_ID, cb.BUDGET_YEAR, cb.BUDGET_QUARTER, CASE cb.COST_CATEGORY WHEN 1 THEN '人工成本' WHEN 2 THEN '材料成本' WHEN 3 THEN '制造费用' WHEN 4 THEN '其他成本' ELSE '未知' END AS BUDGET_TYPE_NAME, cc.CENTER_CODE, cc.CENTER_NAME, cb.TOTAL_BUDGET AS BUDGET_AMOUNT, cb.ACTUAL_COST AS USED_AMOUNT, cb.REMAINING_BUDGET, CASE WHEN cb.TOTAL_BUDGET > 0 THEN ROUND((cb.ACTUAL_COST / cb.TOTAL_BUDGET) * 100, 2) ELSE 0 END AS EXECUTION_RATE, CASE cb.STATUS WHEN 0 THEN '草稿' WHEN 1 THEN '生效中' WHEN 2 THEN '已冻结' WHEN 3 THEN '已关闭' ELSE '未知' END AS BUDGET_STATUS_NAME, u.REALNAME AS CREATOR_NAME, cb.REMARK, cb.CREATE_TIME, cb.UPDATE_TIME, TO_CHAR(cb.BOOK_ID) AS BOOK_ID FROM "REDACTED"."T_COST_BUDGET" cb LEFT JOIN "REDACTED"."T_COST_CENTER" cc ON cb.CENTER_ID = cc.CENTER_ID LEFT JOIN TBL_STAFF u ON cb.CREATOR = u.STAFFID WHERE cb.IS_DELETED = 0
AND cb.BUDGET_YEAR = #{param.budgetYear}
AND cb.CENTER_ID = #{param.centerId}
AND cb.BOOK_ID = #{param.bookId}
AND cb.TENANT_ID = #{param.tenantId}
ORDER BY cb.CREATE_TIME DESC

SELECT TO_CHAR(t.CONTROL_ID) AS control_id, t.CONTROL_NO AS control_no, TO_CHAR(t.CENTER_ID) AS cost_center_id, cc.CENTER_NAME AS cost_center_name, cc.CENTER_CODE AS cost_center_code, t.CONTROL_TYPE AS control_type, CASE t.CONTROL_TYPE WHEN 1 THEN '预算控制' WHEN 2 THEN '限额控制' WHEN 3 THEN '审批控制' ELSE '未知' END AS control_type_name, t.CONTROL_AMOUNT AS budget_amount, COALESCE(b.ACTUAL_COST, 0) AS actual_amount, CASE WHEN t.CONTROL_AMOUNT > 0 THEN LEAST(ROUND(COALESCE(b.ACTUAL_COST, 0) * 100.0 / t.CONTROL_AMOUNT, 0), 999) ELSE 0 END AS usage_rate, t.WARNING_THRESHOLD AS warning_threshold, t.CONTROL_STRATEGY AS control_strategy, t.CONTROL_DESC AS control_desc, CASE WHEN t.CONTROL_AMOUNT > 0 AND COALESCE(b.ACTUAL_COST, 0) >= t.CONTROL_AMOUNT THEN 3 WHEN t.CONTROL_AMOUNT > 0 AND COALESCE(b.ACTUAL_COST, 0) * 100.0 / t.CONTROL_AMOUNT >= t.WARNING_THRESHOLD THEN 2 ELSE 1 END AS warning_status, CASE WHEN t.CONTROL_AMOUNT > 0 AND COALESCE(b.ACTUAL_COST, 0) >= t.CONTROL_AMOUNT THEN '超支' WHEN t.CONTROL_AMOUNT > 0 AND COALESCE(b.ACTUAL_COST, 0) * 100.0 / t.CONTROL_AMOUNT >= t.WARNING_THRESHOLD THEN '预警' ELSE '正常' END AS warning_status_name, t.IS_ENABLED AS is_enabled, t.CREATE_TIME AS create_time, t.UPDATE_TIME AS update_time FROM T_COST_CONTROL t LEFT JOIN T_COST_CENTER cc ON t.CENTER_ID = cc.CENTER_ID AND cc.IS_DELETED = 0 LEFT JOIN ( SELECT CENTER_ID, SUM(COALESCE(ACTUAL_COST, 0)) AS ACTUAL_COST FROM T_COST_BUDGET WHERE IS_DELETED = 0
AND BUDGET_YEAR = SUBSTR(#{param.controlPeriod}, 1, 4)
GROUP BY CENTER_ID ) b ON t.CENTER_ID = b.CENTER_ID WHERE t.IS_DELETED = 0
AND t.BOOK_ID = #{param.bookId}
AND t.TENANT_ID = #{param.tenantId}
AND t.CENTER_ID = #{param.costCenterId,jdbcType=VARCHAR}
AND t.CONTROL_TYPE = #{param.controlType}
AND CASE WHEN t.CONTROL_AMOUNT > 0 AND COALESCE(b.ACTUAL_COST, 0) >= t.CONTROL_AMOUNT THEN 3 WHEN t.CONTROL_AMOUNT > 0 AND COALESCE(b.ACTUAL_COST, 0) * 100.0 / t.CONTROL_AMOUNT >= t.WARNING_THRESHOLD THEN 2 ELSE 1 END = #{param.warningStatus}
ORDER BY t.CREATE_TIME DESC

SELECT COUNT(1)
FROM T_COST_CONTROL t
WHERE t.IS_DELETED = 0

    AND t.BOOK_ID = #{param.bookId}


    AND t.TENANT_ID = #{param.tenantId}


    AND t.CENTER_ID = #{param.costCenterId,jdbcType=VARCHAR}


    AND t.CONTROL_TYPE = #{param.controlType}

SELECT COUNT(CASE WHEN warning_status = 1 THEN 1 END) AS normal_centers, COUNT(CASE WHEN warning_status = 2 THEN 1 END) AS warning_centers, COUNT(CASE WHEN warning_status = 3 THEN 1 END) AS exceed_centers, COUNT(1) AS total_controls, COALESCE(SUM(t.CONTROL_AMOUNT), 0) AS total_budget, COALESCE(SUM(b_actual), 0) AS total_actual, CASE WHEN COALESCE(SUM(t.CONTROL_AMOUNT), 0) > 0 THEN ROUND(COALESCE(SUM(b_actual), 0) * 100.0 / SUM(t.CONTROL_AMOUNT), 2) ELSE 0 END AS overall_execution_rate FROM ( SELECT t.CONTROL_AMOUNT, COALESCE(b.ACTUAL_COST, 0) AS b_actual, CASE WHEN t.CONTROL_AMOUNT > 0 AND COALESCE(b.ACTUAL_COST, 0) >= t.CONTROL_AMOUNT THEN 3 WHEN t.CONTROL_AMOUNT > 0 AND COALESCE(b.ACTUAL_COST, 0) * 100.0 / t.CONTROL_AMOUNT >= t.WARNING_THRESHOLD THEN 2 ELSE 1 END AS warning_status FROM T_COST_CONTROL t LEFT JOIN ( SELECT CENTER_ID, SUM(COALESCE(ACTUAL_COST, 0)) AS ACTUAL_COST FROM T_COST_BUDGET WHERE IS_DELETED = 0 GROUP BY CENTER_ID ) b ON t.CENTER_ID = b.CENTER_ID WHERE t.IS_DELETED = 0 AND t.IS_ENABLED = 1
AND t.BOOK_ID = #{param.bookId}
AND t.TENANT_ID = #{param.tenantId}
) t

SELECT TO_CHAR(cc.CENTER_ID) AS center_id, cc.CENTER_NAME AS center_name, COALESCE(SUM(cb.TOTAL_BUDGET), 0) AS budget_amount, COALESCE(SUM(cb.ACTUAL_COST), 0) AS actual_amount, (COALESCE(SUM(cb.ACTUAL_COST), 0) - COALESCE(SUM(cb.TOTAL_BUDGET), 0)) AS variance, CASE WHEN COALESCE(SUM(cb.TOTAL_BUDGET), 0) > 0 THEN ROUND( (COALESCE(SUM(cb.ACTUAL_COST), 0) - COALESCE(SUM(cb.TOTAL_BUDGET), 0)) * 100.0 / SUM(cb.TOTAL_BUDGET), 1) ELSE 0 END AS variance_rate, CASE WHEN COALESCE(SUM(cb.TOTAL_BUDGET), 0) = 0 THEN 3 ELSE GREATEST(1, LEAST(5, 5 - CAST(ABS( (COALESCE(SUM(cb.ACTUAL_COST), 0) - SUM(cb.TOTAL_BUDGET)) * 100.0 / SUM(cb.TOTAL_BUDGET) ) / 20 AS INT) )) END AS efficiency FROM T_COST_CENTER cc LEFT JOIN T_COST_BUDGET cb ON cc.CENTER_ID = cb.CENTER_ID AND cb.IS_DELETED = 0
AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD >= #{param.startPeriod})
AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD <= #{param.endPeriod})
WHERE cc.IS_DELETED = 0
AND cc.BOOK_ID = #{param.bookId}
AND cc.TENANT_ID = #{param.tenantId}
AND cc.CENTER_ID IN
#{cid,jdbcType=VARCHAR}
GROUP BY cc.CENTER_ID, cc.CENTER_NAME ORDER BY actual_amount DESC, cc.CENTER_ID

SELECT COUNT(1)
FROM T_COST_CENTER cc
WHERE cc.IS_DELETED = 0

    AND cc.BOOK_ID = #{param.bookId}


    AND cc.TENANT_ID = #{param.tenantId}


    AND cc.CENTER_ID IN

        #{cid,jdbcType=VARCHAR}

SELECT COALESCE(cb.BUDGET_PERIOD, cb.BUDGET_YEAR) AS period, cc.CENTER_NAME AS center_name, COALESCE(cb.COST_CATEGORY, '年度预算') AS cost_type, COALESCE(cb.ACTUAL_COST, 0) AS amount, CASE WHEN tot.total_actual > 0 THEN ROUND(COALESCE(cb.ACTUAL_COST, 0) * 100.0 / tot.total_actual, 1) ELSE 0 END AS proportion, 0 AS growth_rate, cb.REMARK AS remark FROM T_COST_BUDGET cb LEFT JOIN T_COST_CENTER cc ON cb.CENTER_ID = cc.CENTER_ID AND cc.IS_DELETED = 0 CROSS JOIN ( SELECT COALESCE(SUM(ACTUAL_COST), 0) AS total_actual FROM T_COST_BUDGET WHERE IS_DELETED = 0
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
) tot WHERE cb.IS_DELETED = 0
AND cb.BOOK_ID = #{param.bookId}
AND cb.TENANT_ID = #{param.tenantId}
AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD >= #{param.startPeriod})
AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD <= #{param.endPeriod})
AND cb.CENTER_ID IN
#{cid,jdbcType=VARCHAR}
ORDER BY period DESC, cb.CENTER_ID OFFSET #{param.offset,jdbcType=NUMERIC} ROWS FETCH NEXT #{param.pageSize,jdbcType=NUMERIC} ROWS ONLY

SELECT COUNT(1)
FROM T_COST_BUDGET cb
WHERE cb.IS_DELETED = 0

    AND cb.BOOK_ID = #{param.bookId}


    AND cb.TENANT_ID = #{param.tenantId}


    AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD >= #{param.startPeriod})


    AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD <= #{param.endPeriod})


    AND cb.CENTER_ID IN

        #{cid,jdbcType=VARCHAR}

SELECT COALESCE(SUM(s.actual_cost), 0) AS total_cost, 0 AS total_cost_trend, CASE WHEN s.center_count > 0 THEN ROUND(COALESCE(SUM(s.actual_cost), 0) / s.center_count, 2) ELSE 0 END AS avg_cost, CASE WHEN COALESCE(SUM(s.total_budget), 0) > 0 THEN ROUND( (COALESCE(SUM(s.actual_cost), 0) - SUM(s.total_budget)) * 100.0 / SUM(s.total_budget), 1) ELSE 0 END AS cost_variance, CASE WHEN COALESCE(SUM(s.total_budget), 0) > 0 THEN GREATEST(0, ROUND(100 - ABS( (COALESCE(SUM(s.actual_cost), 0) - SUM(s.total_budget)) * 100.0 / SUM(s.total_budget) ), 1)) ELSE 0 END AS efficiency_index FROM ( SELECT cb.TOTAL_BUDGET AS total_budget, cb.ACTUAL_COST AS actual_cost, (SELECT COUNT(1) FROM T_COST_CENTER WHERE IS_DELETED = 0
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
) AS center_count FROM T_COST_BUDGET cb WHERE cb.IS_DELETED = 0
AND cb.BOOK_ID = #{param.bookId}
AND cb.TENANT_ID = #{param.tenantId}
AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD >= #{param.startPeriod})
AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD <= #{param.endPeriod})
) s GROUP BY s.center_count

SELECT CASE UPPER(COALESCE(cb.COST_CATEGORY, '')) WHEN 'PRODUCTION' THEN '生产成本' WHEN 'SALES' THEN '销售成本' WHEN 'PROCUREMENT' THEN '采购成本' WHEN 'INVEST' THEN '投资成本' WHEN 'HR' THEN '人力成本' WHEN 'BRANCH' THEN '分支机构' WHEN 'MANAGEMENT' THEN '管理成本' WHEN 'RESEARCH' THEN '研发成本' WHEN 'FINANCE' THEN '财务成本' WHEN 'LOGISTICS' THEN '物流成本' WHEN '' THEN '未分类' ELSE cb.COST_CATEGORY END AS name, COALESCE(SUM(cb.ACTUAL_COST), 0) AS value FROM T_COST_BUDGET cb WHERE cb.IS_DELETED = 0
AND cb.BOOK_ID = #{param.bookId}
AND cb.TENANT_ID = #{param.tenantId}
AND (cb.BUDGET_PERIOD = #{param.analysisPeriod} OR cb.BUDGET_YEAR = #{param.analysisPeriod})
GROUP BY CASE UPPER(COALESCE(cb.COST_CATEGORY, '')) WHEN 'PRODUCTION' THEN '生产成本' WHEN 'SALES' THEN '销售成本' WHEN 'PROCUREMENT' THEN '采购成本' WHEN 'INVEST' THEN '投资成本' WHEN 'HR' THEN '人力成本' WHEN 'BRANCH' THEN '分支机构' WHEN 'MANAGEMENT' THEN '管理成本' WHEN 'RESEARCH' THEN '研发成本' WHEN 'FINANCE' THEN '财务成本' WHEN 'LOGISTICS' THEN '物流成本' WHEN '' THEN '未分类' ELSE cb.COST_CATEGORY END ORDER BY value DESC

SELECT COALESCE(cb.BUDGET_PERIOD, cb.BUDGET_YEAR) AS period, COALESCE(SUM(cb.ACTUAL_COST), 0) AS actual_amount, COALESCE(SUM(cb.TOTAL_BUDGET), 0) AS budget_amount FROM T_COST_BUDGET cb WHERE cb.IS_DELETED = 0
AND cb.BOOK_ID = #{param.bookId}
AND cb.TENANT_ID = #{param.tenantId}
AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD >= #{param.startPeriod})
AND (cb.BUDGET_PERIOD IS NULL OR cb.BUDGET_PERIOD <= #{param.endPeriod})
GROUP BY COALESCE(cb.BUDGET_PERIOD, cb.BUDGET_YEAR) ORDER BY period FETCH FIRST 12 ROWS ONLY

SELECT COUNT(DISTINCT cc.CENTER_ID) AS TOTAL_CENTERS, NVL(SUM(cb.BUDGET_AMOUNT), 0) AS TOTAL_COST, NVL(AVG(cb.BUDGET_AMOUNT), 0) AS AVG_COST, ROUND(DBMS_RANDOM.VALUE(-10, 10), 2) AS COST_VARIANCE, ROUND(DBMS_RANDOM.VALUE(80, 95), 1) AS EFFICIENCY_INDEX FROM T_COST_CENTER cc LEFT JOIN T_COST_BUDGET cb ON cc.CENTER_ID = cb.CENTER_ID AND cb.IS_DELETED = 0 WHERE cc.IS_DELETED = 0
AND cc.BOOK_ID = #{param.bookId}
AND cc.TENANT_ID = #{param.tenantId}

SELECT
    (SELECT COUNT(1) FROM T_COST_CENTER WHERE IS_DELETED = 0
     AND BOOK_ID = #{param.bookId}
     AND TENANT_ID = #{param.tenantId}
    ) as totalCenters,
    COALESCE((SELECT SUM(ACTUAL_COST) FROM T_COST_BUDGET WHERE IS_DELETED = 0
     AND BOOK_ID = #{param.bookId}
     AND TENANT_ID = #{param.tenantId}
    ), 0) as totalCost,
    COALESCE((SELECT SUM(ACTUAL_COST) FROM T_COST_BUDGET WHERE IS_DELETED = 0
    AND BUDGET_PERIOD = #{param.currentPeriod}
     AND BOOK_ID = #{param.bookId}
     AND TENANT_ID = #{param.tenantId}
    ), 0) as monthlyCost,
    COALESCE((SELECT
        CASE WHEN SUM(TOTAL_BUDGET) > 0 THEN
            ROUND((SUM(ACTUAL_COST) - SUM(TOTAL_BUDGET)) / SUM(TOTAL_BUDGET) * 100, 2)
        ELSE 0 END
    FROM T_COST_BUDGET WHERE IS_DELETED = 0
     AND BOOK_ID = #{param.bookId}
     AND TENANT_ID = #{param.tenantId}
    ), 0) as costVariance
FROM DUAL
